      "policy_source_id": "q12",
      "interpretation": "The `create_shipment` tool call must include all required fields (e.g., `contents` is provided, but `weight_kg` is incorrect and `declared_value_eur` is missing if applicable).",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h29",
